using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the DI container provides IHttpClientFactory automatically.
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClient = httpClientFactory.CreateClient("WeatherApi");
    }

    [McpServerTool, Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true";
        var response = await _httpClient.GetFromJsonAsync<JsonElement>(url);

        if (response.TryGetProperty("current_weather", out var weather))
        {
            var temp = weather.GetProperty("temperature").GetDouble();
            var wind = weather.GetProperty("windspeed").GetDouble();
            return $"Temperature: {temp}°C, Wind: {wind} km/h";
        }

        return "Unable to retrieve weather data.";
    }

    [McpServerTool, Description("Get the geocoding coordinates for a city name.")]
    public async Task<string> GeocodeCity(
        [Description("City name to look up")] string city)
    {
        var url = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1";
        var response = await _httpClient.GetFromJsonAsync<JsonElement>(url);

        if (response.TryGetProperty("results", out var results) &&
            results.GetArrayLength() > 0)
        {
            var first = results[0];
            var lat = first.GetProperty("latitude").GetDouble();
            var lon = first.GetProperty("longitude").GetDouble();
            var name = first.GetProperty("name").GetString();
            return $"{name}: latitude={lat}, longitude={lon}";
        }

        return $"No results found for '{city}'.";
    }
}

